#!/usr/bin/env python3
"""MES2 QC Hold v1.3 — Bulk QC Unhold from filtered inventory.

Run from Interplex_MES_BE with this file in sibling Interplex_MES_FE:
 python ../Interplex_MES_FE/IPTH_MES2_QC_Hold_BulkUnhold_v1_3_Updater.py --scan
 python ../Interplex_MES_FE/IPTH_MES2_QC_Hold_BulkUnhold_v1_3_Updater.py --apply
 python ../Interplex_MES_FE/IPTH_MES2_QC_Hold_BulkUnhold_v1_3_Updater.py --verify
 python ../Interplex_MES_FE/IPTH_MES2_QC_Hold_BulkUnhold_v1_3_Updater.py --rollback

Source baseline: previously released QC Hold SearchCSV v1.2.
Code+Markdown only; DOES NOT CONNECT TO SQL SERVER OR CHANGE BUSINESS DATA.
Requires database QC Hold V0003 already applied.
Rejects unexpected file content rather than overwriting local changes.
"""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import zlib

RELEASE = "MES2_QC_Hold_BulkUnhold_v1_3_20261118"
MANIFEST = [{'path': 'Interplex_MES_BE/app/api/v1/endpoints/qc_batch_hold.py', 'before': 'f0fdd416e95acda14aa7c3c5d64a7b4d039bb20321ab64147b9ab5310b11db48', 'after': '1d9f5229a8b83afebe2d9e672fdc7f7e18632f9174728fe5afacc5a367b5f1a9', 'size': 20846}, {'path': 'Interplex_MES_FE/src/api/qcBatchAPI.js', 'before': 'cd292391fc994c5d3bd32f19eb12d1339b59f91c84aa4e498d011d8a041be9c7', 'after': '9a44cd656705ba8e5a0586e05211ed05faa323c1255a2f8699f6fa1e5cde29b3', 'size': 689}, {'path': 'Interplex_MES_FE/src/components/utilities/BatchHoldView.jsx', 'before': 'e01bbdad1051a84874e796b75a67dc9cd7dc5837cd059bcec9ac3f14af2611e5', 'after': 'b6448b1d4c4588660d13fb305e60542c184dc9ef4549a43571de6e6303f5c9eb', 'size': 24878}, {'path': 'Interplex_MES_FE/src/components/utilities/BatchHoldWorkspace.css', 'before': '3489c6f6169d59db5e25bd5f33917e7b7dc97e49c8d702a4217b2dfb7fe6dce5', 'after': 'dc7910fe84146e16e3168f6855ea758dacd4736b6a4db6da49c7cef222a78499', 'size': 11850}, {'path': 'Interplex_MES_FE/docs/mes_agent/modules/BATCH_HOLD_AND_BATCH_TRACE.md', 'before': '740ecd4847b81b50089aebf02b62f32254ff540f5f657dc4003740596fb9ce09', 'after': '872dbd28195b5e9f9fd9165771d524f64a5c2711fd9d9595f8e5a2f159bb582c', 'size': 6026}, {'path': 'Interplex_MES_FE/docs/mes_agent/CHANGELOG.md', 'before': 'bd07f804b60ad382a6b007e2d877d8e5f1c58d10434486477d1b0b5e7058c989', 'after': 'e90f9860ef83661c9d5285e1c5e610fe2e7e9a863f36d52f7087cbb2761a4366', 'size': 6472}, {'path': 'Interplex_MES_FE/docs/mes_agent/changes/2026-11-18-qc-hold-v1-3-bulk-unhold.md', 'before': None, 'after': 'f8b596babb2a95fc39c6d04db4d985bfb9bf9a6009f71b55705ce981ba99054b', 'size': 1331}]
PAYLOADS = {'Interplex_MES_BE/app/api/v1/endpoints/qc_batch_hold.py': '', 'Interplex_MES_FE/src/api/qcBatchAPI.js': '', 'Interplex_MES_FE/src/components/utilities/BatchHoldView.jsx': '', 'Interplex_MES_FE/src/components/utilities/BatchHoldWorkspace.css': '', 'Interplex_MES_FE/docs/mes_agent/modules/BATCH_HOLD_AND_BATCH_TRACE.md': '', 'Interplex_MES_FE/docs/mes_agent/CHANGELOG.md': '', 'Interplex_MES_FE/docs/mes_agent/changes/2026-11-18-qc-hold-v1-3-bulk-unhold.md': ''}


def sha(blob):
    return hashlib.sha256(blob).hexdigest()


def disk_hash(path):
    return sha(path.read_bytes()) if path.is_file() else None


def get_project():
    if Path.cwd().resolve().name != 'Interplex_MES_BE':
        raise RuntimeError('REJECT: run from Interplex_MES_BE (CWD), not FE.')
    fe=Path(__file__).resolve().parent
    if fe.name!='Interplex_MES_FE' or not (fe/'package.json').exists():
        raise RuntimeError('REJECT: place updater at Interplex_MES_FE project root.')
    project=fe.parent
    if not (project/'Interplex_MES_BE/app/api/v1/api.py').is_file():
        raise RuntimeError('REJECT: sibling Interplex_MES_BE/app/api/v1/api.py missing.')
    for repo in ['Interplex_MES_FE','Interplex_MES_BE']:
        result=subprocess.run(['git','-C',str(project/repo),'rev-parse','--abbrev-ref','HEAD'],capture_output=True,text=True)
        if result.returncode or result.stdout.strip()!='phase2':
            raise RuntimeError('REJECT: '+repo+' expected branch phase2, got '+result.stdout.strip())
    return project


def inspect(project):
    before=after=0
    fail=[]
    for item in MANIFEST:
        actual=disk_hash(project/item['path'])
        if actual==item['before']:
            before+=1
            print('[BEFORE]',item['path'])
        elif actual==item['after']:
            after+=1
            print('[AFTER]',item['path'])
        else:
            print('[REJECT]',item['path'], 'actual=',actual)
            fail.append(item['path'])
    if before and after:
        fail.append('mixed partial installation')
    if fail:
        print('VERDICT: REJECT — source mismatch or partial installation')
        return 'REJECT'
    if after:
        print('VERDICT: ALREADY_APPLIED')
        return 'ALREADY_APPLIED'
    print('VERDICT: PASS — ready to APPLY code/docs only')
    return 'PASS'


def payload(item):
    data=zlib.decompress(base64.b64decode(PAYLOADS[item['path']]))
    if sha(data)!=item['after']:
        raise RuntimeError('REJECT: corrupt payload '+item['path'])
    return data


def write_atomic(target,blob):
    target.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=target.parent,prefix='.qc-v13-',delete=False) as f:
        tmp=Path(f.name)
        f.write(blob);f.flush();os.fsync(f.fileno())
    try:os.replace(tmp,target)
    finally:tmp.unlink(missing_ok=True)


def backup_path():
    return Path.home()/'.ipth_mes_updater_backups'/RELEASE


def apply(project):
    state=inspect(project)
    if state=='ALREADY_APPLIED':
        print('NO-OP: already installed');return
    if state!='PASS':raise RuntimeError('REJECT: source conflict')
    decoded={item['path']:payload(item) for item in MANIFEST}
    backup=backup_path()
    if backup.exists():
        raise RuntimeError('REJECT: backup exists — do not overwrite: '+str(backup))
    previous=[]
    backup.mkdir(parents=True)
    try:
        for item in MANIFEST:
            target=project/item['path']
            original=target.read_bytes() if target.exists() else None
            previous.append((target,original))
            if original is not None:
                dest=backup/item['path'];dest.parent.mkdir(parents=True,exist_ok=True)
                dest.write_bytes(original)
                if disk_hash(dest)!=item['before']:
                    raise RuntimeError('BACKUP FAIL: '+item['path'])
        (backup/'manifest.json').write_text(json.dumps(MANIFEST,indent=2),encoding='utf-8')
        for item in MANIFEST:
            target=project/item['path'];write_atomic(target,decoded[item['path']])
            if disk_hash(target)!=item['after']:
                raise RuntimeError('WRITE FAIL: '+item['path'])
            print('[APPLIED]',item['path'])
    except BaseException:
        print('[RECOVERY] Restoring previous source...')
        for target,original in reversed(previous):
            try:
                if original is None: target.unlink(missing_ok=True)
                else:write_atomic(target,original)
            except Exception as error:print('[CRITICAL]',target,error)
        shutil.rmtree(backup,ignore_errors=True)
        raise
    print('APPLIED: QC Bulk Unhold v1.3, FE/BE/Markdown only; NO SQL operations.')
    print('BACKUP:',backup)


def verify(project):
    if inspect(project)!='ALREADY_APPLIED':
        raise RuntimeError('VERIFY FAILED: files differ from installed v1.3 release')
    for item in MANIFEST:payload(item)
    print('VERIFY PASS — all 7 patched files match release and payload checksums.')


def rollback(project):
    backup=backup_path()
    if not backup.is_dir():raise RuntimeError('REJECT: no backup found at '+str(backup))
    if inspect(project)!='ALREADY_APPLIED':
        raise RuntimeError('REJECT: installed files have local changes; rollback aborted')
    if json.loads((backup/'manifest.json').read_text(encoding='utf-8'))!=MANIFEST:
        raise RuntimeError('REJECT: backup manifest mismatch')
    for item in MANIFEST:
        if item['before'] is not None and disk_hash(backup/item['path'])!=item['before']:
            raise RuntimeError('REJECT: damaged backup '+item['path'])
    for item in reversed(MANIFEST):
        target=project/item['path']
        if item['before'] is None:target.unlink(missing_ok=True)
        else:write_atomic(target,(backup/item['path']).read_bytes())
        if disk_hash(target)!=item['before']:
            raise RuntimeError('CRITICAL: rollback verify failure '+item['path'])
        print('[ROLLED BACK]',item['path'])
    shutil.rmtree(backup)
    print('ROLLBACK PASS — source/docs restored; backup retired; database unchanged.')


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group(required=True)
    for opt in ['scan','apply','verify','rollback']:
        group.add_argument('--'+opt,action='store_true')
    args=parser.parse_args()
    project=get_project()
    if args.scan:
        if inspect(project)=='REJECT':sys.exit(2)
    elif args.apply:apply(project)
    elif args.verify:verify(project)
    elif args.rollback:rollback(project)

if __name__=='__main__':
    try:main()
    except Exception as error:
        print(type(error).__name__+': '+str(error),file=sys.stderr)
        sys.exit(2)
